window.ScripturaLexicons.BDAG_PART_0362 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-01\" data-source=\"BDAG\" data-search=\"τρῆμα, ατος, τό substantivo neutro abertura; orifício BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρῆμα, ατος, τό</td><td>substantivo neutro</td><td>abertura; orifício</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-02\" data-source=\"BDAG\" data-search=\"τριάκοντα numeral cardinal trinta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τριάκοντα</td><td>numeral cardinal</td><td>trinta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-03\" data-source=\"BDAG\" data-search=\"τριακόσιοι, αι, α numeral cardinal trezentos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τριακόσιοι, αι, α</td><td>numeral cardinal</td><td>trezentos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-04\" data-source=\"BDAG\" data-search=\"τρίβολος, ου, ὁ substantivo masculino cardo; erva espinhosa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρίβολος, ου, ὁ</td><td>substantivo masculino</td><td>cardo; erva espinhosa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-05\" data-source=\"BDAG\" data-search=\"τριβολώδης, ες adjetivo cheio de cardos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τριβολώδης, ες</td><td>adjetivo</td><td>cheio de cardos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-06\" data-source=\"BDAG\" data-search=\"τρίβος, ου, ἡ substantivo feminino trilha; caminho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρίβος, ου, ἡ</td><td>substantivo feminino</td><td>trilha; caminho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-07\" data-source=\"BDAG\" data-search=\"τριετής, ες adjetivo de três anos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τριετής, ες</td><td>adjetivo</td><td>de três anos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-08\" data-source=\"BDAG\" data-search=\"τριετία, ας, ἡ substantivo feminino período de três anos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τριετία, ας, ἡ</td><td>substantivo feminino</td><td>período de três anos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-09\" data-source=\"BDAG\" data-search=\"τρίζω verbo ranger BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρίζω</td><td>verbo</td><td>ranger</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-10\" data-source=\"BDAG\" data-search=\"τρίμηνος, ον adjetivo de três meses BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρίμηνος, ον</td><td>adjetivo</td><td>de três meses</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-11\" data-source=\"BDAG\" data-search=\"τρίς advérbio três vezes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρίς</td><td>advérbio</td><td>três vezes</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-12\" data-source=\"BDAG\" data-search=\"τρίστεγον, ου, τό substantivo neutro terceiro pavimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρίστεγον, ου, τό</td><td>substantivo neutro</td><td>terceiro pavimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-13\" data-source=\"BDAG\" data-search=\"τρισχίλιοι, αι, α numeral cardinal três mil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρισχίλιοι, αι, α</td><td>numeral cardinal</td><td>três mil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-14\" data-source=\"BDAG\" data-search=\"τρίτος, η, ον numeral ordinal terceiro; terço BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρίτος, η, ον</td><td>numeral ordinal</td><td>terceiro; terço</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-15\" data-source=\"BDAG\" data-search=\"τρίχινος, η, ον adjetivo feito de pelos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρίχινος, η, ον</td><td>adjetivo</td><td>feito de pelos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-16\" data-source=\"BDAG\" data-search=\"τρόμος, ου, ὁ substantivo masculino tremor; estremecimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρόμος, ου, ὁ</td><td>substantivo masculino</td><td>tremor; estremecimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-17\" data-source=\"BDAG\" data-search=\"τροπή, ῆς, ἡ substantivo feminino volta; mudança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τροπή, ῆς, ἡ</td><td>substantivo feminino</td><td>volta; mudança</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-18\" data-source=\"BDAG\" data-search=\"τρόπος, ου ὁ substantivo masculino modo; maneira; conduta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρόπος, ου ὁ</td><td>substantivo masculino</td><td>modo; maneira; conduta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-19\" data-source=\"BDAG\" data-search=\"τροποφορέω verbo suportar; tolerar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τροποφορέω</td><td>verbo</td><td>suportar; tolerar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0362-20\" data-source=\"BDAG\" data-search=\"τροφεύς, έως, ὁ substantivo masculino nutridor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τροφεύς, έως, ὁ</td><td>substantivo masculino</td><td>nutridor</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0362-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρῆμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρῆμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">τετραίνω</span> ‘perfurar’; Aristoph., Hippocr., Pla.+; PRyl 21 Fgm. 3 II, 5 [I a.C.]; EpArist 61=Jos., Ant. 12, 66) abertura, orifício <span class=\"greek\">τρῆμα</span> <span class=\"greek\">ῥαφίδος</span> olho de uma agulha <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:24</a> v.l. (em lugar de <span class=\"greek\">τρύπημα</span>). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:25</a> v.l. (em lugar de <span class=\"greek\">τρυμάλια</span>). Também <span class=\"greek\">τρῆμα</span> <span class=\"greek\">βελόνης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:25</a>. V. a literatura em <span class=\"greek\">κάμηλος</span>, <span class=\"greek\">κάμιλος</span>, <span class=\"greek\">τρυμαλιά</span>.—DELG s.v. <span class=\"greek\">τετραίνω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τριάκοντα</h1><div class=\"entry-meta\"><span>numeral cardinal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τριάκοντα</span> (<span class=\"greek\">τρεῖς</span>,-<span class=\"greek\">κοντα</span>; v. Schwyzer I 593) indecl. (Hom.; poeta cômico CGFP 366, 56 et al.) trinta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:8</a>, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:8</a>, 20 (rendimento de trinta por um de cereais na península Táurica: Strabo 7, 4, 6 p. 311. Quanto ao rendimento do trigo em solo fértil, v. GDalman, PJ 22, 1926, 129–31); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:15</a>; 27:3, 5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:23</a> (Porphyr., Vi. Plot. 4 <span class=\"greek\">ὢν</span> <span class=\"greek\">ἐτῶν</span> <span class=\"greek\">τρ</span>.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:19</a>; Hv 4, 2, 1 (como sinal numérico <span class=\"greek\">λ</span>´ ); Hs 6, 4, 4. <span class=\"greek\">τρ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀκτώ</span> trinta e oito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:5</a>. <span class=\"greek\">τετρακόσια</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:17</a>. Em Hs 9, 4, 3; 9, 5, 4; 9, 15, 4 o sinal numérico <span class=\"greek\">λε</span>´ = <span class=\"greek\">τριάκοντα</span> <span class=\"greek\">πεντε</span> trinta e cinco (Just., A I, 34, 2; <span class=\"greek\">τριάκοντα</span> <span class=\"greek\">ἕξ</span> D. 132, 1).—DELG s.v. <span class=\"greek\">τρεῖς</span> e <span class=\"greek\">διακόσιοι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τριακόσιοι, αι, α</h1><div class=\"entry-meta\"><span>numeral cardinal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τριακόσιοι</span>, <span class=\"greek\">αι</span>, <span class=\"greek\">α</span> (<span class=\"greek\">τρεῖς</span>,-<span class=\"greek\">κοσιοι</span>; v. Schwyzer I 593; Hom.+; inscrições, papiros, LXX; TestAbr B 3 p. 107, 7 [Stone p. 62]; TestJob 15:4; GrBar; Jos., Bell. 1, 625, Ant. 11, 15; Just., D. 32, 4 <span class=\"greek\">τριακόσια</span> <span class=\"greek\">πεντήκοντα</span> <span class=\"greek\">ἔτη</span>; Ath. 31, 1) trezentos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:5</a>; B 9:8a (com <span class=\"greek\">διαοκτώ</span> Gen 14:14; Jos., Ant. 1, 178), 8b, 8c (em referência ao <span class=\"greek\">τ</span> em <span class=\"greek\">σταῦρος</span>).—DELG s.v. <span class=\"greek\">τρεῖς</span> e <span class=\"greek\">διακόσιοι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρίβολος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρίβολος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Alcaeus [600 a.C.] 100 Diehl [sobre isso v. MTreu, Alkaios2 ’63, 169 n.]; Aristoph., Theophr. et al.; inscrições, papiros, LXX; TestSol 12:2 [v. aparato]; ApcMos 24; ApcrEzk P 1 v. 5; Philo, Somn. 2, 161) a respeito de ervas espinhosas, especialmente o cardo, que cresce na Palestina em grande abundância e infinita variedade. Pl. Hs 9, 20, 3. Com <span class=\"greek\">ἄκανθαι</span> (Gen 3:18; Hos 10:8; ApcMos 24; ApcrEzk) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:8</a>; Hs 6, 2, 6f; 9, 1, 5; 9, 20, 1.—ILöw, Aram. Pflanzennamen 1881 §302, D. Flora der Juden IV ’34, 660 (índice); LFonck, Streifzüge durch die bibl. Flora 1900; FLundgreen, Die Pflanzen im NT: NKZ 28, 1917, 828ff; GDalman, PJ 22, 1926, 126ff (com ilustração), Arbeit I 407, 2: silva; Zohary 159 (talvez centaurea iberica).—Kl. Pauly II 105; BHHW I 350f. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τριβολώδης, ες</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τριβολώδης</span>, <span class=\"greek\">ες</span> (<span class=\"greek\">τρίβολος</span>,-<span class=\"greek\">ώδης</span>) cheio de cardos Hs 6, 2, 6.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρίβος, ου, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρίβος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">τρίβω</span> ‘esfregar’; hinos homéricos, Hdt. et al.; inscrições: APF 1, 1901, p. 221, 21; PRainer 42, 14; LXX; Jos., Ant. 15, 347) trilha ou rota definida, caminho</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> a respeito de um caminho familiar e muito percorrido, caminho batido (<span class=\"greek\">τρίβω</span>) Hm 6, 1, 3.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> caminho em geral <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:4</a> (os três Is 40:3; cf. também SibOr 3, 777).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> fig., a respeito de modos de conduta estabelecidos <span class=\"greek\">τὰς</span> <span class=\"greek\">τρίβους</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> (cf. Pr 16:17; SibOr 3, 721) Hs 5, 6, 3.—DELG s.v. <span class=\"greek\">τρίβω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τριετής, ες</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τριετής</span>, <span class=\"greek\">ες</span> (<span class=\"greek\">τρεῖς</span>, <span class=\"greek\">ἔτος</span>; Hom., Od. 2, 106 e 13, 277 adv. <span class=\"greek\">τρίετες</span>; Hdt., Pla., inscrições, papiros; LXX <span class=\"greek\">τρίετες</span>) de/por três anos <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">τρ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">παῖς</span> a menina (Maria) tinha três anos de idade GJs 7:2.—DELG s.v. <span class=\"greek\">τρεῖς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τριετία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τριετία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">τριέτης</span>; Theophr. et al.; Plut., Lucian; Artem. 4, 1 p. 202, 9; OGI 669, 35; papiros; Jos., Ant. 19, 351.—B-D-F §5, 3) período de três anos, três anos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:18</a> D, 31.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρίζω</span> (intr. Hom., Hdt. et al., igualmente Am 2:13 Aq; Is 38:14 Sym. [fut. <span class=\"greek\">τρίσω</span>]) originalmente ‘emitir um grito estridente’, a respeito de sons produzidos por aves (Hom. et al.), depois a respeito de uma variedade de sons, incluindo o rangido de objetos móveis, também a respeito de dentes que rangem (Epicharmus, Fgm. 21 Kaibel, Com. Gr. Fgm. p. 94, em Athen. 10, 411b), trans. na única passagem em que ocorre em nossa literatura, ranger, triturar <span class=\"greek\">τρίζειν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὀδόντας</span> ranger os dentes (Ps.-Callisth. 3, 22, 13 [duas vezes]; Cyranides p. 46, 5; TestSol 12:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:18</a>. V. B-D-F §148, 1.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρίμηνος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρίμηνος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">τρεῖς</span>, <span class=\"greek\">μήν</span>; Soph.et al.) de três meses, como subst. <span class=\"greek\">ἡ</span> <span class=\"greek\">τρίμηνος</span> (Hdt. 2, 124; Aeschin. 3, 70; PLond I, 18, 10 p. 23 [161 a.C.]; PSI 689, 5; 30. V. B-D-F §241, 3: subentende-se <span class=\"greek\">περίοδος</span>) ou <span class=\"greek\">τὸ</span> <span class=\"greek\">τρίμηνον</span> (Polyb. 1, 38, 6; 5, 1, 12; Plut., Crass. 550 [12, 3]; Ptolem. 1, 8, 6.—Duvidoso <span class=\"greek\">ἐν</span> <span class=\"greek\">τριμήνῳ</span>: SIG 527, 114 [talvez 220 a.C.]; 1023, 31; Jos., Ant. 3, 62; <span class=\"greek\">διὰ</span> <span class=\"greek\">τριμήνου</span> PLond II, 306, 22 p. 119 [II d.C.]; LXX) (período de) três meses <span class=\"greek\">τρίμηνον</span> (acus. em resposta à pergunta: por quanto tempo? 4 Km 24:8; 2 Ch 36:2.—B-D-F §161, 2; Rob. 469–71) durante três meses <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:23</a>.—DELG s.v. <span class=\"greek\">τρεῖς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρίς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρίς</span> (adv.; sobre a formação Schwyzer I 597; Hom. et al.; Ael. Aristid. 30, 23 K.=10 p. 122 D.: <span class=\"greek\">ὦ</span> <span class=\"greek\">τρὶς</span> <span class=\"greek\">εὐδαίμονες</span>; inscrições, LXX, Joseph.) três vezes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:34</a>, 75; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:30</a>, 72; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:34</a>, 61; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:25ab</a>; 12:8; D 7:3; Hs 9, 6, 3 v.l.; MPol 12:1. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τρίς</span> (CIG 1122, 9; PGM 36, 273= <span class=\"greek\">εἰς</span> <span class=\"greek\">τρίς</span>, encontrado desde Pind., Hdt., também Jos., Ant. 5, 348) três vezes, nas duas passagens em que ocorre em nossa literatura provavelmente=(ainda) uma terceira vez (PHolm 1, 18) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:16</a>; 11:10.—DELG s.v. <span class=\"greek\">τρεῖς</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρίστεγον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρίστεγον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">τρεῖς</span>, <span class=\"greek\">στέγη</span>) terceiro pavimento de um edifício, terceiro pavimento, o segundo acima do nível do solo (Gen 6:16 Sym.—Neut. de <span class=\"greek\">τρίστεγος</span>=‘de três pavimentos’ [Dionys. Hal. 3, 68; Jos., Bell. 5, 220; papiros]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:9</a>.—M-M s.v. <span class=\"greek\">τρίστεγος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρισχίλιοι, αι, α</h1><div class=\"entry-meta\"><span>numeral cardinal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρισχίλιοι</span>, <span class=\"greek\">αι</span>, <span class=\"greek\">α</span> (<span class=\"greek\">τρεῖς</span>, <span class=\"greek\">χίλιοι</span>; Hom. et al.; papiros, LXX; En 7:2; TestJob; Jos., Bell. 2, 500, Vi. 213; 233; Just., A I, 31, 8) três mil Ac 2:41 (sobre o número dos convertidos, cf. Iambl., Vi. Pyth. §29 [LDeubner, SBBerlAk ’35, XIX p. 54].—Caso os números em Ac 2:41 e 4:4 se referissem originalmente ao mesmo acontecimento ou relato dele, cf. então Appian, Bell. Civ. 3, 42 §173: uns, por um lado, dizem <span class=\"greek\">χίλιοι</span>, outros <span class=\"greek\">τρισχίλιοι</span>. <span class=\"greek\">διαφέρονται</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀριθμοῦ</span> ‘pois divergem quanto ao número’. Também 2, 70 §289f com a conclusão: ‘tão inexatos são os relatos de números’ na tradição; 2, 82 §345f).—DELG s.v. <span class=\"greek\">τρεῖς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρίτος, η, ον</h1><div class=\"entry-meta\"><span>numeral ordinal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρίτος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">τρεῖς</span>; Hom.+)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> terceiro numa série, terceiro</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> empregado como adj., com um substantivo que muitas vezes pode ser suprido pelo contexto <span class=\"greek\">ἕως</span> <span class=\"greek\">τρίτου</span> <span class=\"greek\">οὐρανοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:2</a> (GrBar 10:1; ApcSed 2:4; ApcMos 37.—IdeVuippens, Le Paradis terrestre au troisième ciel 1925. Também EPeterson, TLZ 52, 1927, 78–80. Mais literatura s.v. <span class=\"greek\">οὐρανός</span> 1e). <span class=\"greek\">τὸ</span> <span class=\"greek\">τρίτον</span> <span class=\"greek\">ζῷον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:7</a>. Cf. 6:5ab; 8:10a; 11:14. <span class=\"greek\">τρίτον</span> <span class=\"greek\">γένος</span> PtK 2 p. 15, 8 (v. <span class=\"greek\">γένος</span> 3). <span class=\"greek\">τρίτου</span> <span class=\"greek\">βαθμοῦ</span> GJs 7:3. <span class=\"greek\">μίλιον</span> <span class=\"greek\">τρ</span>. 17:2. (<span class=\"greek\">ἐν</span>) <span class=\"greek\">τῇ</span> <span class=\"greek\">τρίτῃ</span> <span class=\"greek\">ἡμέρᾳ</span> (Appian, Liby. 122 §578; JosAs 29:8; AscIs 3:16; Just., D. 97, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:21</a>; 17:23; 20:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:22</a>; 24:7, 46; Ac 10:40. <span class=\"greek\">τῇ</span> <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">τρίτῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:4</a>. (SMcCasland, The Scripture Basis of ‘On the Third Day’: JBL 48, 1929, 124–37; GLandes, JBL 86, ’67, 446–50 [Jonas]. V. s.v. <span class=\"greek\">τρεῖς</span>). <span class=\"greek\">ἕως</span> <span class=\"greek\">τρίτης</span> <span class=\"greek\">ἡμέρας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.64\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:64</a> (cf. TestAbr A 20 p. 103, 23 [Stone p. 54] <span class=\"greek\">ἕως</span> <span class=\"greek\">τρίτης</span> <span class=\"greek\">ἡμέρας</span>). <span class=\"greek\">μετὰ</span> <span class=\"greek\">τρίτην</span> <span class=\"greek\">ἡμέραν</span> depois de três dias (Appian, Iber. 43 §177) Ac 10:40 D. <span class=\"greek\">τρίτη</span> <span class=\"greek\">ὥρα</span> (=nove horas da manhã) 20:3 ou <span class=\"greek\">ὥρα</span> <span class=\"greek\">τρίτη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:25</a> (AMahoney, CBQ 28, ’66, 292–99); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:15</a>. <span class=\"greek\">τρίτη</span> <span class=\"greek\">ὥρα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">νυκτός</span> (=nove horas da noite, como em TestAbr A 5 p. 82, 11 [Stone p. 12]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:23</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">τρ</span>. <span class=\"greek\">φυλακῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:38</a>.—<span class=\"greek\">τρίτην</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">ἡμέραν</span> (Lucian, Dial. Mort. 13, 3; Achilles Tat. 7, 11, 2; v. <span class=\"greek\">ἄγω</span> 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:21</a>. <span class=\"greek\">ἄλλος</span> <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">τρίτος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:9</a>.—O substantivo é suprido pelo contexto (Diog. L. 2, 46 <span class=\"greek\">Ἀριστοτέλης</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τρίτῳ</span> [isto é, livro] <span class=\"greek\">περὶ</span> <span class=\"greek\">ποιητικῆς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:12</a>, 31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:4</a>; 21:19. <span class=\"greek\">τῇ</span> <span class=\"greek\">τρίτῃ</span> (subentende-se <span class=\"greek\">ἡμέρᾳ</span>. Igualmente <span class=\"greek\">τῇ</span> <span class=\"greek\">τρίτῃ</span> GDI p. 874, n50b, 3 [Quios, cerca de 600 a.C.]; Demosth. [I d.C.] em Aëtius 186, 16; Appian, Bell. Civ. 2, 88 §369; Arrian, Anab. 7, 11, 1. Cf. Jos., Vi. 229 <span class=\"greek\">εἰς</span> <span class=\"greek\">τρίτην</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:32</a> (olhando para o futuro depois de <span class=\"greek\">σήμερον</span> e <span class=\"greek\">αὔριον</span>=depois de amanhã; cf. Epict. 4, 10, 31; 4, 12, 21; M. Ant. 4, 47.—Olhando retrospectivamente para o passado, o terceiro dia equivaleria a ‘anteontem’. Cf. Ps.-Lucian, Halc c. 3 <span class=\"greek\">ἑώρας</span> <span class=\"greek\">τρίτην</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">ὅσος</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">χειμών</span>=anteontem experimentaste quão severa era a tempestade); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:19</a>. Subentende-se <span class=\"greek\">ἔτος</span> GJs 7:1.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> empregado como adv. <span class=\"greek\">τὸ</span> <span class=\"greek\">τρίτον</span> a terceira vez (Hom. et al.; PLips 33 II, 15; TestAbr A 13 p. 92, 18 [Stone p. 32]), <span class=\"greek\">τρίτον</span> uma terceira vez (Aeschyl. et al.; Jos., Ant. 8, 371), ambos no sentido de pela terceira vez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:17ab</a>. No mesmo sentido <span class=\"greek\">ἐκ</span> <span class=\"greek\">τρίτου</span> (Pla., Tim. 54b; ParJer 7:8; Aelian, VH 14, 46) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:44</a>. <span class=\"greek\">τρίτον</span> <span class=\"greek\">τοῦτο</span> agora pela terceira vez, esta é a terceira vez (Judg 16:15) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:14</a>; 13:1. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">τρίτον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:14</a> (v. FNeirynck, ETL 64, ’88, 431f). Em enumerações (<span class=\"greek\">τὸ</span>) <span class=\"greek\">τρίτον</span> em terceiro lugar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:28</a>; D 16:6 (cf. Pla., Rep. 2, 358c; Plut., Mor. 459d; Just., A I, 26, 1; Iambl., Vi. Pyth. 29, 165 <span class=\"greek\">πρῶτον</span> … <span class=\"greek\">δεύτερον</span> … <span class=\"greek\">τρίτον</span>; 30, 171).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> como subst., a terça parte de algo, terço, terça parte <span class=\"greek\">τὸ</span> <span class=\"greek\">τρίτον</span> (subentende-se <span class=\"greek\">μέρος</span>; v. B-D-F §241, 7.—<span class=\"greek\">τὸ</span> <span class=\"greek\">τρ</span>. neste sentido Diod S 17, 30, 3; Lucian, Tox. 46 <span class=\"greek\">τὸ</span> <span class=\"greek\">τρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀτιμίας</span>; PFlor 4, 17; 19; Mitt-Wilck. I/2, 402 I, 18 <span class=\"greek\">τὸ</span> <span class=\"greek\">νενομισμένον</span> <span class=\"greek\">τρίτον</span>=o terço em conformidade com a lei; Num 15:6, 7) a terça parte, um terço, seguido de gen. partitivo (Appian, Illyr. 26 §75 <span class=\"greek\">τὸ</span> <span class=\"greek\">τρ</span>. <span class=\"greek\">τούτων</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:7–12</a>; 9:15, 18; 12:4.—DELG s.v. <span class=\"greek\">τρεῖς</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρίχινος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρίχινος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">θρίξ</span>; X., Pla.+; papiros, LXX) feito de pelos <span class=\"greek\">σάκκος</span> (frequentemente nos papiros, p. ex. PSI 427, 3 [III a.C.]; PHamb 10, 39) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:12</a>.—DELG s.v. <span class=\"greek\">θρίξ</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρόμος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρόμος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">τρέμω</span>; Hom. et al.; PSI 135, 10; LXX; pseudepígrafos; Philo, Leg. ad Gai. 267; Just., D. 67, 10) tremor, estremecimento causado pelo medo, com <span class=\"greek\">ἔκστασις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:8</a>. Principalmente combinado com <span class=\"greek\">φόβος</span> (como em Gen 9:2; Ex 15:16; Dt 2:25; 11:25 al.; En 13:3; JosAs) <span class=\"greek\">μετὰ</span> <span class=\"greek\">φόβου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τρόμου</span> (JosAs 16:7 A) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:12</a> (v. <span class=\"greek\">κατεργάζομαι</span> 2). <span class=\"greek\">ἐν</span> <span class=\"greek\">φόβῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τρόμῳ</span> (cf. Is 19:16; Ps 2:1; JosAs 14:10; ApcSed 14:12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:3</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">φόβος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τρόμος</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐπέπεσεν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">κατοικοῦσιν</span> <span class=\"greek\">αὐτήν</span> 1 Cl 12:5 (cf. Ex 15:16; Jdth 2:28). <span class=\"greek\">τρόμος</span> <span class=\"greek\">με</span> <span class=\"greek\">ἔλαβεν</span> Hv 3, 1, 5 (cf. Ex 15:15; Is 33:14; pl.: ApcMos 25 <span class=\"greek\">ἐν</span> <span class=\"greek\">πολλοῖς</span> <span class=\"greek\">τρόμοις</span>).—B. 1153. DELG s.v. <span class=\"greek\">τρέμω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τροπή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τροπή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">τρέπω</span>; Hom. et al.) o processo de voltar-se, volta, rotação, mudança (Pla., Plut. et al.; Jos. Ant. 10, 191; Just., D. 85, 5; Mel., P. 21, 147 [‘reversão, destruição’]; Ath. 22, 4). Em nossa literatura a palavra ocorre somente em <span class=\"greek\">τροπῆς</span> <span class=\"greek\">ἀποσκίασμα</span>. obscurecimento causado pela rotação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:17</a>. O contexto (v. <span class=\"greek\">φῶς</span> 2) sugere linguagem figurada baseada na associação de <span class=\"greek\">τρ</span>. com fenômenos astrais, como o ‘solstício’ (Hom. et al.; SIG 1264, 5; PHib 27, 120; 210 [III a.C.] <span class=\"greek\">ἡλίου</span> <span class=\"greek\">τροπή</span>; PRyl 27; Sb 358, 6; Dt 33:14; Wsd 7:18) ou, mais geralmente, os ‘movimentos’ dos corpos celestes de um lugar nos céus ou de uma constelação para outra (Pla., Tim. 39d; Aristot., HA 5, 9; Sext. Emp., Math. 5, 11; Philo, Agr. 51; Ath. 22, 7; Heath, Aristarchus 33 n. 3). Caso o texto esteja em ordem correta (mas v. comentários ad loc.; Goodsp., Probs. 189f; as vv.ll. incluem <span class=\"greek\">τροπὴ</span> <span class=\"greek\">ἀποσκιάσματος</span>, <span class=\"greek\">τροπῆς</span> <span class=\"greek\">ἀποσκιάσματος</span>), o sentido mais geral (movimentos) deve ser preferido ao mais especializado (solstício), e a expressão <span class=\"greek\">τροπῆς</span> <span class=\"greek\">ἀποσκίασμα</span> (v. <span class=\"greek\">ἀποσκίασμα</span>) significa obscurecimento que tem sua origem na mudança. Que Deus, em contraste com tudo o mais, é imutável era uma verdade frequentemente expressa na teologia helenística (Herm. Wr. em Stob. I p. 277 Wachsm.=p. 432, 15 Sc. <span class=\"greek\">τί</span> <span class=\"greek\">θεός</span>; <span class=\"greek\">ἄτρεπτον</span> <span class=\"greek\">ἀγαθόν</span>. <span class=\"greek\">τί</span> <span class=\"greek\">ἄνθρωπος</span>; <span class=\"greek\">τρεπτὸν</span> <span class=\"greek\">κακόν</span>; Philo, Leg. All. 2, 89 <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄλλα</span> <span class=\"greek\">τρέπεται</span>, <span class=\"greek\">μόνος</span> <span class=\"greek\">αὐτὸς</span> [=<span class=\"greek\">θεός</span>] <span class=\"greek\">ἄτρεπτός</span> <span class=\"greek\">ἐστι</span>; 33, Deus Imm. 22, Poster. Caini 19).—A tradução de <span class=\"greek\">τροπ</span>. <span class=\"greek\">ἀποσκ</span>. como ‘sombra (=vestígio) de mudança’, que gozou de certa voga desde Ecumênio e Teofilacto até HEwald et al., é lexicalmente improvável.—DELG s.v. <span class=\"greek\">τρέπω</span> C3. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρόπος, ου ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρόπος</span>, <span class=\"greek\">ου</span> <span class=\"greek\">ὁ</span> (<span class=\"greek\">τρέπω</span>; Pind., Hdt.+).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> a maneira pela qual algo é feito, maneira, modo, espécie, aparência <span class=\"greek\">εἰς</span> <span class=\"greek\">δούλου</span> <span class=\"greek\">τρόπον</span> <span class=\"greek\">κεῖσθαι</span> apresentar-se sob a aparência de (=como) um escravo (<span class=\"greek\">κεῖμαι</span> 3c) Hs 5, 5, 5; 5, 6, 1.—<span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">τρόπῳ</span> de toda maneira (3 Macc 7:8 v.l.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:16</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τρόπον</span> de toda maneira ou em todos os aspectos (X., An. 6, 6, 30 al.; Num 18:7; EpArist 215; Philo, Op. M. 10; SibOr 3, 430) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:2</a>; IEph 2:2; ITr 2:3; ISm 10:1; IPol 3:2. <span class=\"greek\">μὴ</span> … <span class=\"greek\">κατὰ</span> <span class=\"greek\">μηδένα</span> <span class=\"greek\">τρόπον</span> de modo nenhum, não … de maneira alguma (SIG 799, 20 <span class=\"greek\">μηδὲ</span> … <span class=\"greek\">κατὰ</span> <span class=\"greek\">μηδένα</span> <span class=\"greek\">τρόπον</span>; 588, 44; PAmh 35, 28; 3 Macc 4:13b <span class=\"greek\">μὴ</span> … <span class=\"greek\">κατὰ</span> <span class=\"greek\">μηδένα</span> <span class=\"greek\">τρ</span>.; 4 Macc 4:24; 10:7; Just., D. 35, 7; cf. JosAs cod. A 23:1 [p. 75, 8 Bat.] <span class=\"greek\">οὐ</span> … <span class=\"greek\">κατ</span>’ <span class=\"greek\">οὐδένα</span> <span class=\"greek\">τρ</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:3</a>. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">τρόπον</span> da mesma maneira que (POxy 237 VIII, 29 <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἔδει</span> <span class=\"greek\">τρόπον</span>; CPR 5, 11; 9, 12; 10, 6; BGU 846, 12; 2 Macc 6:20; 4 Macc 14:17 v.l.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:11</a>; 27:25.—No acus. (v. B-D-F §160; Johannessohn, Kasus 81f ) <span class=\"greek\">τρόπον</span> com gen. como (Aeschyl., Hdt. et al.; Philo. Frequentemente com animais: <span class=\"greek\">θηρίων</span> <span class=\"greek\">τρόπον</span> 2 Macc 5:27; 3 Macc 4:9; <span class=\"greek\">σκορπίου</span> <span class=\"greek\">τρόπον</span> 4 Macc 11:10) <span class=\"greek\">σητὸς</span> <span class=\"greek\">τρόπον</span> 1 Cl 39:5 (Job 4:19). <span class=\"greek\">τὸν</span> <span class=\"greek\">ὅμοιον</span> <span class=\"greek\">τρόπον</span> <span class=\"greek\">τούτοις</span> da mesma maneira ou exatamente como eles Jd 7 (cf. Tat. 26, 2 <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὅμοιον</span> <span class=\"greek\">τρόπον</span> <span class=\"greek\">ἡμῖν</span>). <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">τρόπον</span> da maneira pela qual = (assim) como (X., Mem. 1, 2, 59, An. 6, 3, 1; Pla., Rep. 5, 466e; Diod S 3, 21, 1; SIG 976, 35; 849, 13f; PLips 41, 9; Gen 26:29; Ex 14:13; Dt 11:25 e muito frequentemente na LXX; TestJob. 37:3; Jos., Ant. 3, 50, Vi. 412b; Just., A I, 4, 7; Tat. 35, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:28</a> (Ex 2:14); 1 Cl 4:10 (Ex 2:14); 2 Cl 9:4; correspondendo a <span class=\"greek\">οὕτως</span> (SIG 685, 51ff; Josh 10:1; 11:15; Is 10:11; 62:5; Ezk 12:11 al.; Just., A I, 7, 3, D. 94, 5; Mel., P. 42, 293) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:8</a>; 2 Cl 8:2; 12:4. <span class=\"greek\">τίνα</span> <span class=\"greek\">τρόπον</span>; de que maneira? como? (Aristoph., Nub. 170; Pla., Prot. 322c; Jos., C. Ap. 1, 315; Just., A I, 32, 10) 1 Cl 24:4; 47:2 v.l. (lat. quemadmodum).—No dat. (B-D-F §198, 4; Rob. 487.—Papiros [Mayser II/2, p. 281]; Jos., Ant. 5, 339; Just., D. 10, 4; Tat. 17, 1) <span class=\"greek\">παντὶ</span> <span class=\"greek\">τρόπῳ</span> de toda e qualquer maneira (Aeschyl., Thu. et al.; X., Cyr. 2, 1, 13; Pla., Rep. 2, 368c; papiros; 1 Macc 14:35; Jos., Ant. 17, 84; Just., D. 68, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:18</a>. <span class=\"greek\">ποίῳ</span> <span class=\"greek\">τρόπῳ</span>; (Aeschyl., Soph. et al.; TestJos 7:1; ApcrEzk [Epiph 70, 9]) Hv 1, 1, 7 (<span class=\"greek\">τόπῳ</span> Joly). <span class=\"greek\">ποίοις</span> <span class=\"greek\">τρόποις</span> m 12, 3, 1.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> a maneira pela qual uma pessoa se comporta ou vive, modos, costumes, modo de vida (Pind., Hdt. et al; Michel 545, 7; papiros, LXX; Jos., Ant. 12, 252; Tat. 21, 2; SibOr 4, 35; ‘modo de vida, disposição de espírito, conduta, caráter’) Hv 1, 1, 2. <span class=\"greek\">ἀφιλάργυρος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τρόπος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:5</a> (X., Cyr. 8, 3, 49 <span class=\"greek\">τρόπος</span> <span class=\"greek\">φιλέταιρος</span>). Também pl. (Aeschyl. et al.; Appian, Bell. Civ. 4, 95 §398; SIG 783, 11; IG XII/7, 408, 8; EpArist 144) <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">τρόπους</span> <span class=\"greek\">κυρίου</span> ter os modos que o próprio Senhor tinha ou que o Senhor exige dos seus D 11:8.—B. 656. DELG s.v. <span class=\"greek\">τρέπω</span> C 2. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τροποφορέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τροποφορέω</span> (<span class=\"greek\">τρόπος</span>, <span class=\"greek\">φορέω</span>) 1 aor. <span class=\"greek\">ἐτροποφόρησα</span> suportar/tolerar os modos, humores etc. (de alguém) (assim Cicero, Ad Att. 13, 29, 2; escólio sobre Aristoph., Ran. 1479) com acus. de pessoa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:18</a> (Dt 1:31 v.l., embora <span class=\"greek\">τροφοφορεῖν</span> esteja no texto ali, ao passo que na passagem de Ac é uma v.l. [Bruce, Acts ad loc.]—B-D-F §119, 1; Mlt-H. 390. Origen, In Matth. X, 14 p. 16, 16 Klostermann ’35).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0362-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τροφεύς, έως, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τροφεύς</span>, <span class=\"greek\">έως</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">τρέφω</span>; Aeschyl., Pla. et al.; OGI 148, 2 [II a.C.] al.; IGR III, 89, 14 [I d.C.] aquele que distribui gratuitamente alimentos ao povo; Jos., Ant. 9, 127 tutor) nutridor, a respeito de Deus (Philo, Leg. All. 3, 177, Congr. Erud. Gr. 171; Herm. Wr. 16, 12 <span class=\"greek\">ὁ</span> <span class=\"greek\">ἥλιος</span> como <span class=\"greek\">σωτὴρ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τροφεύς</span>; p. 390, 12 Sc. <span class=\"greek\">ὁ</span> <span class=\"greek\">δημιουργός</span> como <span class=\"greek\">πατὴρ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τροφέυς</span>) Dg 9:6.—DELG s.v. <span class=\"greek\">τρέφω</span> C 5.</p></section></article>"};
